<template><main class="support-page">
 <header class="support-hero"><div><span class="support-eyebrow">FACTURA.VIP · MESA DE AYUDA</span><h1>Centro de soporte</h1><p>{{context.name || context.user}} <span v-if="context.superadmin">· Administración central</span></p></div><div class="support-actions"><button v-if="!embedded" @click="returnToWork">Volver a mis actividades</button><button class="support-primary" @click="newTicket">+ Nuevo ticket</button></div></header>
 <nav class="support-nav"><button :class="{selected:tab==='tickets'}" @click="tab='tickets'">Tickets y atenciones</button><button :class="{selected:tab==='reports'}" @click="tab='reports'">Indicadores</button><button v-if="context.superadmin" :class="{selected:tab==='companies'}" @click="showCompanies">Empresas y accesos</button><button v-if="context.superadmin" :class="{selected:tab==='categories'}" @click="tab='categories'">Categorías</button></nav>
 <p v-if="error" role="alert" class="support-error">{{error}}</p><p v-if="success" role="status" class="support-success">{{success}}</p>
 <section v-if="tab==='tickets' || tab==='reports'" class="support-filter"><label>Desde<input type="date" v-model="filters.from"></label><label>Hasta<input type="date" v-model="filters.to"></label><label>Empresa<select v-model="filters.tenant_id"><option value="">Todas las autorizadas</option><option v-for="t in context.tenants" :key="t.id" :value="t.id">{{t.origin_https}} · {{t.external_company_id}}</option></select></label><label>Estado<select v-model="filters.status"><option value="">Todos</option><option v-for="(name,key) in statuses" :key="key" :value="key">{{name}}</option></select></label><label>Prioridad<select v-model="filters.priority"><option value="">Todas</option><option v-for="(name,key) in priorities" :key="key" :value="key">{{name}}</option></select></label><label>Archivo<select v-model="filters.archived" @change="inbox='';filters.status='';loadTickets()"><option value="active">Sin archivar</option><option value="only">Archivados</option><option value="all">Todos, incluido archivo</option></select></label><label>Buscar<input v-model="filters.search" placeholder="Ticket o asunto" @keyup.enter="loadTickets()"></label><button :disabled="loading" @click="loadTickets()">{{loading?'Consultando…':'Consultar'}}</button></section>
 <section v-if="tab==='tickets' || tab==='reports'" class="support-kpis"><article><span>Tickets del filtro</span><strong>{{total}}</strong></article><article><span>Nuevos</span><strong>{{count('new')}}</strong></article><article><span>En atención</span><strong>{{count('in_progress')}}</strong></article><article><span>Resueltos / cerrados</span><strong>{{count('resolved')+count('closed')}}</strong></article><article><span>Escalados</span><strong>{{count('escalated')}}</strong></article></section>
 <section v-if="tab==='tickets'" class="support-desk-toolbar"><div><h2>{{teamAccess?'Mesa de atención':'Mis solicitudes de soporte'}}</h2><p>{{teamAccess?'Cada solicitud tiene un responsable. Acepta un caso de la bandeja y acompaña al cliente hasta confirmar su solución.':'Aquí puedes ver quién te atiende, responder y confirmar la solución.'}}</p></div><div class="support-inbox-tabs" v-if="teamAccess"><button :class="{selected:inbox==='queue'}" @click="setInbox('queue')">Por aceptar</button><button :class="{selected:inbox==='mine'}" @click="setInbox('mine')">Mis atenciones</button><button :class="{selected:inbox===''}" @click="setInbox('')">{{supervises?'Equipo completo':'Mis casos y disponibles'}}</button></div><div class="support-actions"><button @click="board=!board">{{board?'Ver lista':'Ver tablero'}}</button><span class="support-live">Actualiza cada 20 s</span></div></section>
 <section v-if="tab==='tickets' && board" class="support-workboard"><article v-for="lane in lanes" :key="lane.key" class="support-worklane" :class="'lane-'+lane.key"><header><h3>{{lane.title}}</h3><span>{{laneTickets(lane).length}}</span></header><p class="support-lane-hint">{{lane.hint}}</p><button v-for="t in laneTickets(lane)" :key="t.id" class="support-ticket" @click="openTicket(t.id)"><div class="support-card-top"><strong>{{t.code}}</strong><span :class="'priority-'+t.priority">{{priorities[t.priority]}}</span></div><h2>{{t.subject}}</h2><p class="support-ticket-requester">{{t.requester_name || 'Cliente'}} · {{t.affected_module}}</p><div class="support-owner" :class="{'is-unassigned':!t.technician_id}"><span class="support-avatar">{{(t.assigned_name || '?').slice(0,1).toUpperCase()}}</span><span>{{t.assigned_name || 'Pendiente de aceptar'}}</span></div><footer>{{date(t.created_at)}} · {{statuses[t.status]}}</footer><span class="support-card-cta">{{!t.technician_id && teamAccess?'Abrir y aceptar atención':'Ver conversación y avances'}} →</span></button><p v-if="!laneTickets(lane).length" class="support-lane-empty">Sin casos en esta etapa</p></article></section>
 <section v-if="tab==='tickets' && !board" class="support-ticket-grid"><button v-for="t in tickets" :key="t.id" class="support-ticket" @click="openTicket(t.id)"><div class="support-card-top"><strong>{{t.code}}</strong><span :class="'priority-'+t.priority">{{priorities[t.priority]}}</span></div><h2>{{t.subject}}</h2><p>{{t.description}}</p><div class="support-tags"><span>{{statuses[t.status]}}</span><span>{{t.affected_module}}</span></div><div class="support-owner">Responsable: {{t.assigned_name || 'Pendiente de aceptar'}}</div><footer>{{t.origin_https}}<br>{{date(t.created_at)}}</footer></button><p v-if="!loading && !tickets.length">No hay tickets para estos filtros y permisos.</p></section><button v-if="tab==='tickets' && next" :disabled="loading" @click="loadTickets(true)">Cargar más tickets</button>
 <section v-if="tab==='reports'" class="support-panel"><h2>Indicadores del periodo consultado</h2><p>Tiempos transcurridos desde la creación del ticket. La primera respuesta mide un mensaje público del técnico; los avisos automáticos no cuentan. Las calificaciones corresponden a opiniones del cliente.</p><div class="support-kpis"><article><span>Empresas con tickets</span><strong>{{metrics.companies || 0}}</strong></article><article><span>Primera respuesta pública</span><strong>{{minutes(metrics.response_minutes)}}</strong></article><article><span>Resolución</span><strong>{{minutes(metrics.resolution_minutes)}}</strong></article></div><h3>Distribución por técnico</h3><div class="support-table"><table><thead><tr><th>Técnico</th><th>Tickets</th><th>Resueltos / cerrados</th><th>Respuesta</th><th>Solución</th><th>Calificación</th></tr></thead><tbody><tr v-for="r in byTechnician" :key="r.technician_id || 'unassigned'"><td>{{r.technician_name || (r.technician_id?'Técnico #'+r.technician_id:'Sin asignar')}}</td><td>{{r.total}}</td><td>{{r.resolved}}</td><td>{{minutes(r.response_minutes)}}</td><td>{{minutes(r.resolution_minutes)}}</td><td>{{r.rating_count?Number(r.rating).toFixed(1)+' / 5 · '+r.rating_count+' opiniones':'Sin calificaciones'}}</td></tr></tbody></table></div></section>
 <section v-if="tab==='companies' && context.superadmin" class="support-panel"><h2>Empresas conectadas</h2><p>Cada instalación conserva su base. Registra el UUID y la clave pública que genera su conector; la clave privada permanece en su servidor.</p><div class="support-table"><table><thead><tr><th>Origen</th><th>Empresa de origen</th><th>Estado</th></tr></thead><tbody><tr v-for="t in context.tenants" :key="t.id"><td>{{t.origin_https}}</td><td>{{t.external_company_id}}</td><td>{{Number(t.active)?'Habilitada':'Deshabilitada'}}</td></tr></tbody></table></div><details><summary>+ Registrar otra instalación</summary><form class="support-form" @submit.prevent="registerInstallation"><label>Dirección HTTPS de la instalación<input v-model="installation.origin" type="url" placeholder="https://cliente.factura.vip" required></label><label>UUID de instalación<input v-model="installation.uuid" required maxlength="36"></label><label>Identificador de empresa en su base<input v-model="installation.company" required maxlength="100"></label><label>Identificador de clave<input v-model="installation.key_id" required maxlength="80"></label><label>Clave pública Ed25519<textarea v-model="installation.public_key" required maxlength="4096"></textarea></label><button class="support-primary" :disabled="saving">Registrar conexión</button></form></details><h3>Accesos del equipo</h3><p>Los técnicos necesitan una autorización por cada empresa que atenderán.</p><form class="support-form support-form-grid" @submit.prevent="grant"><label>Usuario registrado<select v-model="membership.principal" required><option value="">Seleccionar</option><option v-for="m in uniqueMembers" :key="m.principal_id" :value="m.principal_id">{{m.external_user_id}} · {{m.origin_https}}</option></select></label><label>Empresa<select v-model="membership.tenant" required><option value="">Seleccionar</option><option v-for="t in context.tenants" :key="t.id" :value="t.id">{{t.origin_https}}</option></select></label><label>Rol<select v-model="membership.role"><option value="technician">Técnico</option><option value="supervisor">Supervisor</option><option value="company_admin">Administrador de empresa</option><option value="requester">Solicitante</option></select></label><label><input type="checkbox" v-model="membership.active"> Acceso habilitado</label><button class="support-primary" :disabled="saving">Guardar acceso</button></form><div class="support-table"><table><thead><tr><th>Usuario</th><th>Empresa</th><th>Rol</th><th>Estado</th></tr></thead><tbody><tr v-for="(m,index) in members" :key="index"><td>{{m.external_user_id}}</td><td>{{m.origin_https}}</td><td>{{m.role}}</td><td>{{Number(m.active)?'Habilitado':'Deshabilitado'}}</td></tr></tbody></table></div></section>
 <section v-if="tab==='categories' && context.superadmin" class="support-panel"><h2>Categorías de atención</h2><form class="support-form support-form-grid" @submit.prevent="saveCategory"><label>Nombre<input v-model="category.name" required maxlength="150"></label><label><input type="checkbox" v-model="category.active"> Habilitada</label><button :disabled="saving">{{category.id?'Guardar cambios':'Crear categoría'}}</button><button type="button" @click="category={name:'',active:true}">Limpiar</button></form><div class="support-table"><table><tbody><tr v-for="c in context.categories" :key="c.id"><td>{{c.name}}</td><td>{{Number(c.active)?'Habilitada':'Deshabilitada'}}</td><td><button @click="category={id:c.id,name:c.name,active:!!Number(c.active)}">Editar</button></td></tr></tbody></table></div></section>
 <b-modal v-model="createOpen" title="Nuevo ticket de soporte" modal-class="diary-modal-premium" size="lg" hide-footer><form class="support-form" @submit.prevent="create"><p v-if="modalError" role="alert" class="support-error">{{modalError}}</p><p>El código se genera automáticamente. No incluyas contraseñas, tokens ni claves privadas.</p><label>Empresa<select v-model="form.tenant_id" required><option v-for="t in context.tenants" :key="t.id" :value="t.id">{{t.origin_https}} · {{t.external_company_id}}</option></select></label><label>Asunto<input v-model="form.subject" maxlength="180" required placeholder="¿Qué necesitas resolver?"></label><label>Descripción<textarea v-model="form.description" maxlength="20000" rows="5" required></textarea></label><div class="support-form-grid"><label>Categoría<select v-model="form.category_id" required><option value="">Seleccionar</option><option v-for="c in activeCategories" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Módulo afectado<input v-model="form.module" maxlength="100" required placeholder="Punto de venta, SUNAT, inventarios…"></label><label>Prioridad<select v-model="form.priority"><option v-for="(name,key) in priorities" :key="key" :value="key">{{name}}</option></select></label><label>Sede o sucursal<input v-model="form.branch" maxlength="100"></label></div><button class="support-primary" :disabled="saving">{{saving?'Guardando…':'Registrar ticket'}}</button></form></b-modal>
 <b-modal v-model="detailOpen" :title="detail.ticket?detail.ticket.code:'Ticket'" modal-class="diary-modal-premium" size="lg" hide-footer><section v-if="detail.ticket" class="support-detail"><p v-if="modalError" role="alert" class="support-error">{{modalError}}</p><h2>{{detail.ticket.subject}}</h2><div class="support-tags"><span>{{statuses[detail.ticket.status]}}</span><span>{{priorities[detail.ticket.priority]}}</span><span>{{detail.ticket.affected_module}}</span></div><p class="support-description">{{detail.ticket.description}}</p><section class="support-attention-banner"><span class="support-avatar">{{(detail.ticket.assigned_name || '?').slice(0,1).toUpperCase()}}</span><div><small>{{detail.ticket.technician_id?'RESPONSABLE DE TU ATENCIÓN':'SOLICITUD RECIBIDA'}}</small><strong>{{detail.ticket.assigned_name || 'Buscando un técnico disponible'}}</strong><p>{{attentionHint}}</p></div><form v-if="staff && !detail.ticket.technician_id" class="support-accept-form" @submit.prevent="accept"><label>Tiempo estimado (minutos)<input type="number" v-model.number="acceptMinutes" min="1" max="43200" required placeholder="Ej. 30"></label><button class="support-primary" :disabled="saving">Aceptar y atender ticket</button></form></section><section class="support-estimate-strip"><strong>Solución estimada: {{detail.ticket.expected_resolution_at?date(detail.ticket.expected_resolution_at):'El técnico debe confirmarla'}}</strong><span v-if="detail.ticket.estimated_minutes">{{detail.ticket.estimated_minutes}} min desde la última estimación · Horario de Lima</span><small>Es una estimación. Cualquier cambio queda registrado en el seguimiento.</small></section><p>Solicitante: {{detail.ticket.requester_name || detail.ticket.requester_id}}</p><div v-if="isRequester && detail.ticket.status==='resolved'" class="support-client-confirm"><strong>Tu solución está lista. ¿Ya funciona correctamente?</strong><p>{{detail.ticket.resolution}}</p><button :disabled="saving" @click="clientDecision('closed')">Validar y calificar la atención</button><button :disabled="saving" @click="clientDecision('reopened')">Necesito más ayuda</button></div><p>Creado: {{date(detail.ticket.created_at)}}<br v-if="detail.ticket.first_response_at"><template v-if="detail.ticket.first_response_at">Primera respuesta: {{date(detail.ticket.first_response_at)}}</template></p><form v-if="['superadmin','supervisor'].includes(detail.role)" class="support-form support-form-grid" @submit.prevent="assign"><label>Técnico responsable<select v-model="technician" required><option value="">Seleccionar</option><option v-for="t in detail.technicians" :key="t.id" :value="t.id">{{t.external_user_id}}</option></select></label><button :disabled="saving">Asignar técnico</button></form><details v-if="canManage && transitions.length" class="support-progress-editor"><summary>Registrar avance o solución</summary><form class="support-form support-form-grid" @submit.prevent="transition"><label>Nuevo estado<select v-model="change.status" required><option value="">Seleccionar</option><option v-for="s in transitions" :key="s" :value="s">{{statuses[s]}}</option></select></label><label>Motivo / solución<textarea v-model="change.reason" required maxlength="10000"></textarea></label><button :disabled="saving">Guardar estado</button></form></details><div class="support-kpis"><article><span>Primera respuesta</span><strong>{{elapsed(detail.ticket.created_at,detail.ticket.first_response_at)}}</strong></article><article><span>Resolución desde creación</span><strong>{{elapsed(detail.ticket.created_at,detail.ticket.resolved_at)}}</strong></article><article><span>Trabajo registrado</span><strong>{{detail.minutes || 0}} min</strong></article></div><details v-if="canManage && ['assigned','in_progress','waiting_customer','escalated'].includes(detail.ticket.status)" class="support-estimate-editor"><summary>Actualizar tiempo estimado</summary><form class="support-form support-form-grid" @submit.prevent="updateEstimate"><label>Minutos desde ahora<input type="number" v-model.number="estimate.minutes" required min="1" max="43200"></label><label>Explicación para el cliente<input v-model="estimate.reason" required maxlength="10000" placeholder="Explica el avance y el motivo del nuevo plazo"></label><button :disabled="saving">Actualizar e informar al cliente</button></form></details><div v-if="canManage && detail.ticket.status==='closed'" class="support-actions"><button :disabled="saving" @click="archiveTicket">{{detail.ticket.archived_at?'Restaurar ticket':'Archivar ticket terminado'}}</button><small>Solo se archivan tickets cerrados y confirmados por el cliente.</small></div><h3>Conversación</h3><div class="support-conversation"><article v-for="m in detail.messages" :key="m.id" :class="{'is-internal':m.visibility==='internal'}"><header><strong>{{m.author}}</strong><span>{{date(m.created_at)}} {{m.visibility==='internal'?'· Nota interna':''}}</span></header><p>{{m.body}}</p></article><p v-if="!detail.messages.length">Todavía no hay mensajes.</p></div><p v-if="staff && !canManage" class="support-ownership-note">Acepta la solicitud para responder al cliente. Cada atención debe tener un responsable.</p><div v-if="canManage" class="support-reply-tools"><button @click="draftReply(false)">Preparar saludo</button><button @click="draftReply(true)">Solicitar información</button><small>Revisa el texto antes de enviarlo al cliente.</small></div><form v-if="!staff || canManage" class="support-form" @submit.prevent="send"><label>{{message.internal?'Nota interna del equipo':'Mensaje al cliente / soporte'}}<textarea v-model="message.body" rows="3" maxlength="20000" required></textarea></label><label v-if="staff"><input type="checkbox" v-model="message.internal"> Visible solo para soporte</label><button class="support-primary" :disabled="saving">Enviar mensaje</button></form><details v-if="canManage"><summary>Tiempo de trabajo · {{detail.minutes || 0}} min registrados</summary><form class="support-form support-form-grid" @submit.prevent="worklog"><label>Minutos trabajados<input type="number" v-model.number="work.minutes" min="1" max="1440" required></label><label>Trabajo realizado<input v-model="work.description" maxlength="2000" required></label><button :disabled="saving">Registrar tiempo</button></form></details><details><summary>Historial de estados</summary><article v-for="h in detail.history" :key="h.id" class="support-history"><strong>{{statuses[h.next_status]}} · {{h.actor}}</strong><span>{{date(h.created_at)}}</span><p>{{h.reason}}</p></article></details><form v-if="isRequester && ['resolved','closed'].includes(detail.ticket.status) && !detail.survey" class="support-form support-rating-form" @submit.prevent="rate"><h3>Califica esta atención</h3><p>Tu opinión ayuda a mejorar el servicio de {{detail.ticket.assigned_name || 'nuestro equipo'}}.</p><div class="support-rating-stars" role="group" aria-label="Puntuación de esta atención"><button v-for="n in 5" :key="n" type="button" :class="{chosen:Number(survey.solution)>=n}" :aria-pressed="Number(survey.solution)===n?'true':'false'" :aria-label="n+' de 5 estrellas'" @click="setRating(n)">★</button><span>{{survey.solution?survey.solution+' / 5 · '+ratingLabels[Number(survey.solution)-1]:'Selecciona de 1 a 5 estrellas'}}</span></div><label><input type="checkbox" v-model="survey.solved"> Mi problema fue solucionado</label><details class="support-rating-breakdown"><summary>Valorar rapidez, trato y solución por separado</summary><div class="support-form-grid"><label v-for="(name,key) in surveyLabels" :key="key">{{name}}<select v-model.number="survey[key]"><option value="">Calificar</option><option v-for="n in 5" :key="n" :value="n">{{n}} / 5</option></select></label></div></details><label><input type="checkbox" v-model="survey.recommend"> Recomendaría el servicio</label><label>Comentario<textarea v-model="survey.comment" maxlength="3000"></textarea></label><button :disabled="saving">{{detail.ticket.status==='resolved'?'Calificar y cerrar atención':'Enviar calificación'}}</button></form><p v-if="detail.survey">Calificación recibida: {{detail.survey.solution}} / 5<br><small>{{detail.survey.respondent_name}} · {{date(detail.survey.created_at)}}</small></p></section></b-modal>
</main></template>
<script>
import config from '@/store/config';
const statuses={new:'Nuevo',assigned:'Asignado',in_progress:'En atención',waiting_customer:'Esperando al cliente',escalated:'Escalado',resolved:'Por validar por el cliente',closed:'Cerrado',reopened:'Reabierto',cancelled:'Cancelado'};
export default {data(){return {context:{tenants:[],categories:[]},tab:'tickets',inbox:'',board:true,lanes:[{key:'queue',title:'Por aceptar',hint:'Solicitudes que necesitan responsable',states:['new','assigned','reopened']},{key:'working',title:'En atención',hint:'El técnico trabaja en la solución',states:['in_progress']},{key:'waiting',title:'En seguimiento',hint:'Esperando al cliente o apoyo técnico',states:['waiting_customer','escalated']},{key:'done',title:'Solución y confirmación',hint:'El cliente confirma y califica',states:['resolved','closed','cancelled']}],statuses,priorities:{critical:'Urgente',high:'Alta',medium:'Media',low:'Baja'},tickets:[],stats:[],total:0,next:null,metrics:{},byTechnician:[],loading:false,saving:false,error:'',success:'',modalError:'',filters:{archived:'active',from:'',to:'',tenant_id:'',status:'',priority:'',search:''},createOpen:false,detailOpen:false,form:{},detail:{},technician:'',acceptMinutes:'',estimate:{minutes:'',reason:''},change:{status:'',reason:''},message:{body:'',internal:false},work:{minutes:15,description:''},survey:{solved:true,speed:'',treatment:'',solution:'',recommend:true,comment:''},ratingLabels:['Muy mala','Regular','Buena','Muy buena','Excelente'],surveyLabels:{speed:'Rapidez',treatment:'Trato',solution:'Solución'},members:[],membership:{principal:'',tenant:'',role:'technician',active:true},category:{name:'',active:true},installation:{origin:'',uuid:'',company:'1',key_id:'initial',public_key:''}}},computed:{isRequester(){return !!this.detail.ticket && Number(this.context.principal)===Number(this.detail.ticket.requester_id)},teamAccess(){return !!this.context.superadmin || (this.context.roles||[]).some(r=>['technician','supervisor'].includes(r.role))},supervises(){return !!this.context.superadmin || (this.context.roles||[]).some(r=>r.role==='supervisor')},canManage(){return this.staff && (this.detail.role!=='technician' || (this.detail.ticket && Number(this.detail.ticket.technician_id)===Number(this.context.principal)))},attentionHint(){const t=this.detail.ticket;if(!t)return '';if(t.status==='resolved')return 'La solución fue registrada. El cliente puede confirmarla o pedir más ayuda.';if(t.status==='closed')return 'Atención confirmada. Gracias por ayudarnos a mejorar con tu calificación.';if(t.status==='waiting_customer')return 'Necesitamos tu respuesta para continuar. Escríbenos en la conversación.';if(t.status==='escalated')return 'El caso necesita apoyo especializado y conserva su seguimiento.';return t.technician_id?'Tu técnico te responderá en esta conversación. Recibirás un aviso cuando haya novedades.':'El equipo recibió tu solicitud. Aquí verás el nombre de quien la acepte.'},embedded(){return window.self!==window.top},activeCategories(){return this.context.categories.filter(c=>Number(c.active))},uniqueMembers(){return this.members.filter((m,index,all)=>all.findIndex(x=>x.principal_id===m.principal_id)===index)},staff(){return ['superadmin','supervisor','technician'].includes(this.detail.role)},transitions(){if(!this.detail.ticket)return [];const map={new:['assigned','in_progress','cancelled'],assigned:['in_progress','escalated','cancelled'],in_progress:['waiting_customer','escalated','resolved'],waiting_customer:['in_progress','escalated'],escalated:['assigned','in_progress'],resolved:['closed','reopened'],closed:['reopened'],reopened:['assigned','in_progress'],cancelled:[]};return (map[this.detail.ticket.status]||[]).filter(s=>this.staff?(this.detail.role!=='technician'||!['closed','reopened'].includes(s)):['reopened','cancelled'].includes(s))}},watch:{'$route.query.ticket'(id){if(id)this.openTicket(id);else this.detailOpen=false}},async mounted(){await this.init();if(this.$route.query.ticket)await this.openTicket(this.$route.query.ticket);else if(this.$route.query.new==='1')this.newTicket();this._changed=()=>this.loadTickets();this.$root.$on('support:changed',this._changed);this._poll=setInterval(()=>{if(!document.hidden&&!this.saving){if(this.detailOpen)this.refreshDetail();else if(this.tab==='tickets')this.loadTickets()}},20000)},beforeDestroy(){clearInterval(this._poll);this.$root.$off('support:changed',this._changed)},methods:{returnToWork(){if(this.context.remote)window.top.location.href='/';else this.$router.push('/diario')},
 setRating(n){this.survey.speed=n;this.survey.treatment=n;this.survey.solution=n},draftReply(requestInfo){this.message.internal=false;this.message.body=requestInfo?`Hola, para continuar con tu atención, ¿puedes indicarme qué mensaje aparece y qué pasos realizaste? Gracias.`:`Hola, soy ${this.context.name || this.context.user}, responsable de tu atención. Estoy revisando tu solicitud y te informaré por aquí sobre los avances.`},laneTickets(lane){return this.tickets.filter(t=>lane.states.includes(t.status))},setInbox(inbox){this.inbox=inbox;this.loadTickets()},async clientDecision(status){if(status==='closed'&&!this.detail.survey){this.modalError='Selecciona de 1 a 5 estrellas y confirma que la soluci\u00f3n funciona.';this.$nextTick(()=>{const form=this.$el.querySelector('.support-rating-form');if(form)form.scrollIntoView({behavior:'smooth',block:'center'});});return;}if(await this.act('transition',{id:this.detail.ticket.id,version:this.detail.ticket.version,status,reason:status==='closed'?'Cliente confirma que la solución funciona':'Cliente solicita continuar la atención'})){await this.refreshDetail();await this.loadTickets()}},elapsed(start,end){if(!end)return 'Pendiente';const a=Date.parse(start.replace(' ','T')+'-05:00'),b=Date.parse(end.replace(' ','T')+'-05:00');return Math.max(0,Math.round((b-a)/60000))+' min'},async accept(){if(await this.act('assign',{id:this.detail.ticket.id,technician:this.context.principal,estimated_minutes:this.acceptMinutes})){await this.refreshDetail();await this.loadTickets();this.success='Atención aceptada. El cliente ya puede ver quién lo atiende; envía tu primera respuesta.'}},
 async get(path,params){return (await this.axios.get(config.API+'support/'+path,{params,timeout:15000})).data},async post(action,payload){return (await this.axios.post(config.API+'support/'+action,payload,{headers:{'X-Support-CSRF':this.context.csrf},timeout:20000})).data},failure(e){return e.response&&e.response.data&&e.response.data.error||'No se pudo completar la operación. Revisa tu conexión.'},
 async init(){try{this.context=await this.get('context');await this.loadTickets()}catch(e){this.error=this.failure(e)}},count(status){const row=this.stats.find(s=>s.status===status);return row?Number(row.total):0},minutes(v){return v===null||v===undefined?'Sin datos':Math.round(Number(v))+' min'},date(v){return v?new Intl.DateTimeFormat('es-PE',{dateStyle:'short',timeStyle:'short',timeZone:'America/Lima'}).format(new Date(v.replace(' ','T')+'-05:00')):''},
 async loadTickets(more=false){if(this.loading)return;this.loading=true;this.error='';try{const r=await this.get('tickets',Object.assign({},this.filters,{inbox:this.inbox},more?{before:this.next}:{}));this.tickets=more?this.tickets.concat(r.tickets):r.tickets;this.total=r.total;this.stats=r.stats;this.next=r.next;this.metrics=r.metrics;this.byTechnician=r.by_technician}catch(e){this.error=this.failure(e)}finally{this.loading=false}},
 newTicket(){this.form={tenant_id:this.context.tenant,subject:'',description:'',category_id:'',module:'',priority:'medium',branch:''};this.modalError='';this.createOpen=true},
 async act(action,payload,modal=true){if(this.saving)return false;this.saving=true;this.modalError='';this.error='';try{await this.post(action,payload);return true}catch(e){if(modal)this.modalError=this.failure(e);else this.error=this.failure(e);return false}finally{this.saving=false}},
 async create(){if(await this.act('create',this.form)){this.createOpen=false;this.success='Ticket registrado correctamente.';await this.loadTickets()}},async openTicket(id){this.modalError='';try{this.detail=await this.get('tickets/'+id);this.technician=this.detail.ticket.technician_id||'';this.acceptMinutes='';this.estimate={minutes:'',reason:''};this.survey={solved:true,speed:'',treatment:'',solution:'',recommend:false,comment:''};this.change={status:'',reason:''};this.message={body:'',internal:false};this._messageOperation=null;this._messageDraft=null;this.detailOpen=true;await this.post('notification_read',{id});this.$root.$emit('support:changed')}catch(e){this.error=this.failure(e)}},async refreshDetail(){if(this._refreshing||!this.detail.ticket)return;this._refreshing=true;try{this.detail=await this.get('tickets/'+this.detail.ticket.id)}catch(e){this.modalError=this.failure(e)}finally{this._refreshing=false}},
 async archiveTicket(){const ticket=this.detail.ticket;if(!ticket.archived_at&&!window.confirm('\u00bfEst\u00e1 seguro de archivar '+ticket.code+'? Se conservar\u00e1n sus mensajes, tiempos y evidencias.'))return;if(await this.act(ticket.archived_at?'restore':'archive',{id:ticket.id,version:ticket.version})){await this.refreshDetail();await this.loadTickets();this.$root.$emit('support:changed');}},
 async updateEstimate(){if(await this.act('transition',{id:this.detail.ticket.id,version:this.detail.ticket.version,status:this.detail.ticket.status,reason:this.estimate.reason,estimated_minutes:this.estimate.minutes})){this.estimate={minutes:'',reason:''};await this.refreshDetail();await this.loadTickets()}},async assign(){if(await this.act('assign',{id:this.detail.ticket.id,technician:this.technician})){await this.refreshDetail();await this.loadTickets()}},async transition(){if(await this.act('transition',{id:this.detail.ticket.id,version:this.detail.ticket.version,status:this.change.status,reason:this.change.reason})){this.change={status:'',reason:''};await this.refreshDetail();await this.loadTickets()}},
 operation(){const b=new Uint8Array(16);window.crypto.getRandomValues(b);b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const x=Array.from(b).map(n=>n.toString(16).padStart(2,'0')).join('');return x.slice(0,8)+'-'+x.slice(8,12)+'-'+x.slice(12,16)+'-'+x.slice(16,20)+'-'+x.slice(20)},async send(){const draft=JSON.stringify([this.detail.ticket.id,this.message.body,this.message.internal]);if(this._messageDraft!==draft){this._messageDraft=draft;this._messageOperation=null}this._messageOperation=this._messageOperation||this.operation();if(await this.act('message',{id:this.detail.ticket.id,body:this.message.body,internal:this.message.internal,operation:this._messageOperation})){this._messageOperation=null;this.message.body='';await this.refreshDetail()}},async worklog(){if(await this.act('worklog',Object.assign({id:this.detail.ticket.id},this.work))){this.work.description='';await this.refreshDetail()}},async rate(){if(['speed','treatment','solution'].some(key=>![1,2,3,4,5].includes(Number(this.survey[key])))){this.modalError='Selecciona de 1 a 5 estrellas para calificar la atención.';return;}if(this.detail.ticket.status==='resolved'&&!this.survey.solved){this.modalError='Si el problema contin\u00faa, pulsa Necesito m\u00e1s ayuda para reabrir la atenci\u00f3n.';return;}if(await this.act('survey',Object.assign({id:this.detail.ticket.id,version:this.detail.ticket.version,close:this.detail.ticket.status==='resolved'},this.survey))){await this.refreshDetail();await this.loadTickets();this.$root.$emit('support:changed');}},
 async showCompanies(){this.tab='companies';try{this.members=(await this.get('members')).members}catch(e){this.error=this.failure(e)}},async grant(){if(await this.act('grant',this.membership,false))await this.showCompanies()},async saveCategory(){if(await this.act('category',this.category,false)){this.context=await this.get('context');this.category={name:'',active:true}}},async registerInstallation(){if(await this.act('installation',this.installation,false)){this.context=await this.get('context');this.installation={origin:'',uuid:'',company:'1',key_id:'initial',public_key:''};this.success='Instalación registrada. Configura su conector para comenzar a recibir tickets.'}}
}};
</script>
